import{_ as i,l as o,o as e,c as n,v as t,p as s,x as r,d,i as p,S as L}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"激活稀疏与 ReLU²","description":"","frontmatter":{"title":"激活稀疏与 ReLU²","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/activation-sparsity.md","filePath":"llm/activation-sparsity.md","lastUpdated":1789023840000}'),h={name:"llm/activation-sparsity.md"};function m(c,a,U,_,A,E){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="激活稀疏与-relu2" tabindex="-1">激活稀疏与 ReLU² <a class="header-anchor" href="#激活稀疏与-relu2" aria-label="Permalink to &quot;激活稀疏与 ReLU²&quot;">​</a></h1><div class="epigraph"><p>SwiGLU 几乎每个通道都亮；换成 ReLU 一类半波，FFN 的中间激活可以大部分是零——跳过的是乘加，掩码随 token 变。</p><footer>—— Mirzadeh et al., ReLU Strikes Back, ICLR 2024；对照 GLU 激活在 LLaMA 族的默认</footer></div><p><a href="/llm/sheared-llama">上一课</a> 静态地改架构宽度。本课形状不变：给定 \\(x\\)，FFN 中间哪些通道为 0，就可以跳过对应列。缺口是 <strong>激活稀疏</strong> 与权重稀疏正交——Wanda 的掩码跨样本固定，这里每步不同。后课 Deja Vu 用小网络预测这张动态掩码；本课先问激活函数把零率放到哪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LLaMA 一类用 SwiGLU / SiLU，中间激活很少真零，权重再稀，通道仍要算。ReLU（或 ReLU²，即平方 ReLU）把负半轴打成零，统计上可以出现很高的通道稀疏度。Mirzadeh 等人说明：在可比训练预算下，ReLU 族 LLM 能把这张稀疏变成推理跳过，而不必先做权重剪枝。问题是训练时就要用这种激活；对已经训好的 SwiGLU 基座，不能靠「推理时改 ReLU」白嫖，分布全错。</p><p>稀疏度随层、随 token 变。平均 90% 零不代表每步都能跳 90%：热 token 会点亮更多通道，核必须按最坏或按阈值门控。没有门控核，零仍占 FLOPs。</p><p><span class="marginnote">ReLU²\\((x)=(\\mathrm{ReLU}(x))^2\\) 在部分工作里比 ReLU 更接近 GELU 的平滑正半轴，同时保留精确零。它不是二阶导数魔法，只是形状。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预训练或继续预训练换成 ReLU / ReLU² FFN（门控线性层要改结构，不是只改函数名）。推理：对中间激活做阈值或直接利用精确零，跳过 \\(W_\\mathrm{down}\\) 的对应行（以及 \\(W_\\mathrm{up}\\) 的列，若预判）。与 MoE 不同：没有专家表，跳过的是稠密 FFN 的通道子集，通信模式仍是张量并行，不是 All-to-All。</p><p>对冻结的 SwiGLU 模型，一条弱路径是蒸馏到 ReLU 学生，或只在部分层替换再愈合。不要写成「QLoRA 式即插即用」。</p>',10)),(e(),s(L,null,{default:r(()=>[p(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22token%22%5D%20--%3E%20UP%5B%22%E4%B8%8A%E6%8A%95%E5%BD%B1%22%5D%0A%20%20UP%20--%3E%20ACT%5B%22ReLU%20%2F%20ReLU2%22%5D%0A%20%20ACT%20--%3E%20Z%5B%22%E7%B2%BE%E7%A1%AE%E9%9B%B6%E9%80%9A%E9%81%93%22%5D%0A%20%20Z%20--%3E%20SKIP%5B%22%E8%B7%B3%E8%BF%87%20down%20%E7%9A%84%E5%AF%B9%E5%BA%94%E8%A1%8C%22%5D%0A%20%20SKIP%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>权重稀疏删的是对所有 \\(x\\) 都为零的连接；激活稀疏删的是<strong>这个</strong> \\(x\\) 上碰巧为零的乘加。表达力在权重里仍满，只是每次前向用子集。这更接近 MoE 的「条件计算」，但路由是激活函数本身，没有可学习门，也没有负载均衡项。代价是训练动态与 GLU 不同：负半轴没有梯度，死通道风险回到早期 ReLU 网的老问题，初始化与学习率要重调。</p><p>与 <a href="/llm/lora">LoRA</a> 叠：适配器若加在 FFN 上，会改变哪些通道被点亮，稀疏统计要在合并后重测。服务端按未合并 LoRA 测的零率不能当合并后的数。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把论文平均稀疏度写成稳定加速比。不要在 decode 的 tiny batch 上预期与 prefill 相同的跳过收益。下一课 Deja Vu：连 ReLU 都不必，用预测器估计「哪些 MLP 神经元、哪些头」对当前上下文有用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>激活稀疏是逐 token 的通道零，与固定权重掩码正交。</li><li>ReLU / ReLU² 把零写进函数；SwiGLU 基座不能推理期改装。</li><li>加速取决于门控核与热 token 的最坏零率。</li><li>无专家通信，条件计算发生在稠密 FFN 内部。</li><li>出处：Mirzadeh et al., ICLR 2024。</li></ul>',7))])}const B=i(h,[["render",m]]);export{u as __pageData,B as default};
